function weatherIcon(condition){return `<svg class="weather-icon" viewBox="0 0 32 32" aria-hidden="true">${weatherIcons[condition]||weatherIcons.unknown}</svg>`}
function stashWeatherKey(){const form=$('#weather-form');if(form?.dataset.activeProvider)weatherKeys[form.dataset.activeProvider]=form.elements.weatherApiKey.value}
function showWeatherProvider(provider){const form=$('#weather-form');if(!form)return;stashWeatherKey();form.dataset.activeProvider=provider;form.elements.weatherProvider.value=provider;form.elements.weatherApiKey.value=weatherKeys[provider]||'';const notes={openweathermap:'OpenWeatherMap needs an API key. The forecast can show up to 5 days.', 'open-meteo':'Open-Meteo works without an API key. A saved key uses the customer API. The forecast can show up to 7 days.', weatherapi:'WeatherAPI.com needs an API key. The number of days depends on that plan.', pirateweather:'Pirate Weather needs an API key. The forecast can show up to 7 days.'};const note=$('#weather-provider-note');if(note)note.textContent=`${notes[provider]||''} Each provider keeps its own key.`}
function renderWeather(){const card=$('#weather-card'),weather=dashboard?.weather,show=document.body.dataset.view==='calendar'&&weather?.days?.length;if(!card)return;card.hidden=!show;if(!show)return;const flags=weather.show||{},now=weather.current,nowEl=$('#weather-now');$('#weather-place').textContent=weather.place||'';const nowParts=[];if(flags.current&&now)nowParts.push(`<strong>${now.temperature??'–'}°</strong>`);if(flags.feels&&now&&Number.isFinite(now.feelsLike))nowParts.push(`<small>Feels ${now.feelsLike}°</small>`);if(nowEl){nowEl.hidden=!nowParts.length;nowEl.innerHTML=nowParts.join('')}$('#weather-days').style.gridTemplateColumns=`repeat(${weather.days.length},minmax(0,1fr))`;$('#weather-days').innerHTML=weather.days.map(day=>{const extra=[];if(flags.precip)extra.push(`<small class="weather-extra">Rain ${day.precip??'–'}%</small>`);if(flags.wind)extra.push(`<small class="weather-extra">${day.wind??'–'} ${escape(weather.windUnit||'mph')}</small>`);if(flags.humidity)extra.push(`<small class="weather-extra">Hum ${day.humidity??'–'}%</small>`);return `<div class="weather-day"><span>${escape(day.label)}</span>${weatherIcon(day.condition)}<strong>${day.high??'–'}°</strong><small>${day.low??'–'}°</small>${extra.join('')}</div>`}).join('')}

function monthRange(){const start=new Date(cursor.getFullYear(),cursor.getMonth(),1),end=new Date(cursor.getFullYear(),cursor.getMonth()+1,1);return{start,end}}
async function renderCalendar(){
  const {start,end}=monthRange(),weekStartsOn=me.household.weekStartsOn,{gridStart,cellCount,rollingForward}=calendarGridWindow(start,new Date(),weekStartsOn,pinnedMonth);const titleFormat=new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'});$('#month-title').textContent=rollingForward?`${new Intl.DateTimeFormat(undefined,{month:'long'}).format(start)} – ${titleFormat.format(new Date(start.getFullYear(),start.getMonth()+1,1))}`:titleFormat.format(start);$('.weekdays').innerHTML=Array.from({length:7},(_,i)=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][(weekStartsOn+i)%7]).map(d=>`<div>${d}</div>`).join('');
  const gridEnd=new Date(gridStart);gridEnd.setDate(gridStart.getDate()+cellCount);
  let calendarData={events:[],errors:[]};try{calendarData=await api(`/api/calendar/events?from=${encodeURIComponent(gridStart.toISOString())}&to=${encodeURIComponent(gridEnd.toISOString())}`)}catch(error){calendarData.errors=[{message:error.message}]}
  const warning=$('#calendar-errors');warning.hidden=!calendarData.errors.length;warning.textContent=calendarData.errors.map(e=>e.message).join(' ');
  calendarEvents=calendarData.events.map(e=>({...e,spans:eventSpanDays(e),startValue:e.start.dateTime||e.start.date,endValue:e.end?.dateTime||e.end?.date,local:e.source==='local reminder'}));
  const today=new Date().toLocaleDateString('en-CA');let html='';for(let i=0;i<cellCount;i++){const day=new Date(gridStart);day.setDate(gridStart.getDate()+i);const key=[day.getFullYear(),String(day.getMonth()+1).padStart(2,'0'),String(day.getDate()).padStart(2,'0')].join('-');html+=`<div class="day ${day.getMonth()!==cursor.getMonth()?'outside':''} ${key===today?'today':''}" aria-label="${day.toDateString()}"><span>${day.getDate()}</span><div class="day-events">${calendarEvents.flatMap(e=>e.spans.filter(span=>span.date===key).map(span=>eventButton(e,span))).join('')}</div></div>`}$('#month-grid').style.gridTemplateRows=`repeat(${cellCount/7},minmax(0,1fr))`;$('#month-grid').innerHTML=html;
  const dateKey=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const monthEvents=calendarEvents.flatMap(e=>e.spans.filter(span=>span.date>=dateKey(start)&&span.date<dateKey(end)).map(span=>({event:e,span})));const days=[...new Set(monthEvents.map(item=>item.span.date))];$('#month-agenda').innerHTML=days.length?days.map(date=>`<section class="agenda-day"><h3>${new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date(`${date}T12:00:00`))}</h3>${monthEvents.filter(item=>item.span.date===date).map(item=>eventButton(item.event,item.span).replace('class="event','class="agenda-event')).join('')}</section>`).join(''):empty('No events this month.');
}
function eventButton(event,span={position:'single'}){const index=calendarEvents.indexOf(event),color=/^#[0-9a-f]{6}$/i.test(event.color||'')?event.color:'',continued=span.position!=='single',time=!continued||span.position==='start'?event.start.dateTime?new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(event.start.dateTime)):'':'',mark=span.position==='start'?'›':span.position==='middle'?'‹›':span.position==='end'?'‹':'';return `<button class="event ${event.local?'local':''} ${continued?`span-${span.position}`:''}" data-event="${index}" aria-label="${escapeAttribute(`${event.title}${continued?`, ${span.position==='end'?'ends':span.position==='start'?'starts and continues':'continues'}`:''}`)}" style="${color?`border-left:3px solid ${color}`:''}">${mark?`<span class="span-mark" aria-hidden="true">${mark}</span>`:''}${time?`<small class="event-time">${escape(time)}</small>`:''}<span class="event-title">${escape(event.title)}</span></button>`}
async function loadSettings(){if(me.user?.role!=='adult')return;const weather=await api('/api/household/weather'),weatherForm=$('#weather-form');if(weatherForm){weatherKeys=weather.keys||{};weatherForm.elements.weatherEnabled.checked=weather.enabled;weatherForm.elements.weatherLocation.value=weather.location||'';weatherForm.elements.weatherUnits.value=weather.units||'f';weatherForm.elements.weatherDays.value=String(weather.days||5);weatherForm.elements.weatherShowPrecip.checked=!!weather.showPrecip;weatherForm.elements.weatherShowWind.checked=!!weather.showWind;weatherForm.elements.weatherShowHumidity.checked=!!weather.showHumidity;weatherForm.elements.weatherShowCurrent.checked=!!weather.showCurrent;weatherForm.elements.weatherShowFeels.checked=!!weather.showFeels;weatherForm.dataset.activeProvider='';showWeatherProvider(weather.provider||'openweathermap')}const dimForm=$('#dim-form');if(dimForm){dimForm.elements.dimEnabled.checked=!!me.household.dimEnabled;dimForm.elements.dimStart.value=me.household.dimStart||'21:00';dimForm.elements.dimEnd.value=me.household.dimEnd||'07:00'}const themeForm=$('#theme-form');if(themeForm)themeForm.elements.theme.value=me.household.theme||'green';const [feeds,devices,routines,chores,routineOrder,choreOrder]=await Promise.all([api('/api/calendar/feeds'),api('/api/devices'),api('/api/routines/history'),api('/api/chores/history'),api('/api/routines'),api('/api/chores')]);$('#week-start-form').elements.weekStartsOn.value=me.household.weekStartsOn;feedCatalog=feeds;$('#calendar-feeds').innerHTML=feeds.length?feeds.map((f,index)=>`<div class="feed-order-row"><span class="feed-order-controls"><button type="button" data-feed-move="${f.id}" data-direction="up" ${index?'':'disabled'} aria-label="Move ${escapeAttribute(f.name)} calendar up">↑</button><button type="button" data-feed-move="${f.id}" data-direction="down" ${index===feeds.length-1?'disabled':''} aria-label="Move ${escapeAttribute(f.name)} calendar down">↓</button></span><details><summary><span style="border-left:3px solid ${f.color};padding-left:6px">${escape(f.name)}</span></summary><form class="stack feed-edit" data-feed-edit="${f.id}"><label>Name<input name="name" maxlength="80" value="${escape(f.name)}" required></label><label>Replacement iCal URL<input name="url" type="url" maxlength="4096" autocomplete="off" placeholder="Leave blank to keep current URL"></label><label>Color<input name="color" type="color" value="${f.color}" required></label><label><input name="enabled" type="checkbox" ${f.enabled?'checked':''}> Enabled</label><button>Save calendar</button></form><button data-delete-feed="${f.id}">Delete</button></details></div>`).join(''):empty('No calendar feeds configured.');$('#devices').innerHTML=devices.length?devices.map(d=>`<div><span>${escape(d.device_name)}</span><button data-device="${d.id}">Revoke</button></div>`).join(''):empty('No paired wall displays.');routineCatalog=routineOrder;choreCatalog=choreOrder;$('#routine-order').innerHTML=itemEditor(routineOrder,'routine');$('#chore-order').innerHTML=itemEditor(choreOrder,'chore');$('#routine-history').innerHTML=routines.length?routines.map(r=>`<div class="history-row">${escape(r.completed_on)} · ${escape(r.child_name)} · ${escape(r.title)}</div>`).join(''):empty('No routine completions.');$('#chore-history').innerHTML=chores.length?chores.map(c=>`<div class="history-row">${escape(c.period_key)} · ${escape(c.title)}${c.assignee_name?` · ${escape(c.assignee_name)}`:''}</div>`).join(''):empty('No chore completions.')}
function frequencyLabel(item){if(item.recurrence==='once'||!item.days)return 'One time';const names=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],days=item.days.split(',');if(days.length===7)return 'Every day';if(item.days==='1,2,3,4,5')return 'Weekdays';if(item.days==='0,6')return 'Weekends';return days.map(day=>names[+day]).join(' ')}
function taskTooltip(item,kind){const person=kind==='routine'?(item.child_names||item.child_name):item.assignee_name||'Anyone';const time=kind==='routine'?` · ${{morning:'Morning',after_school:'Afternoon',bedtime:'Bedtime'}[item.period]||'Morning'}`:'';return `${item.title} · ${person}${time} · ${frequencyLabel(item)}. ${kind==='routine'?'Personal habit, checked for each child.':'Household job, checked once.'}`}
function itemEditor(items,kind){return items.length?items.map((item,index)=>`<div class="item-edit" title="${escapeAttribute(taskTooltip(item,kind))}"><div class="item-edit-main"><span class="item-edit-move"><button data-move="${kind}" data-id="${item.id}" data-direction="up" ${index?'':'disabled'} aria-label="Move ${escapeAttribute(item.title)} up">↑</button><button data-move="${kind}" data-id="${item.id}" data-direction="down" ${index===items.length-1?'disabled':''} aria-label="Move ${escapeAttribute(item.title)} down">↓</button></span><span class="item-edit-copy">${escape(item.title)} <small class="muted">${escape(kind==='routine'?(item.child_names||item.child_name):(item.assignee_name||'Anyone'))} · ${kind==='routine'?`${{morning:'Morning',after_school:'Afternoon',bedtime:'Bedtime'}[item.period]||'Morning'} · `:''}${frequencyLabel(item)}${kind==='chore'?rewardLabel(item):''}</small></span></div><span class="item-edit-actions"><button data-edit-${kind}="${item.id}">Edit</button><button data-delete-${kind}="${item.id}">Delete</button></span></div>`).join(''):empty('None yet.')}
function updateHouseholdTitle(){if(me?.household)$('#home-name').textContent=me.household.displayTitle?.trim()||me.household.name.toUpperCase()}
function setupRoutineScheduleSetting(){if(me.user?.role!=='adult')return;let form=$('#routine-schedule-form');if(!form){const panel=document.createElement('section');panel.id='settings-panel-routines';panel.className='settings-panel';panel.dataset.settingsCategory='routines';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','settings-tab-routines');panel.innerHTML='<h3>Routine periods</h3><p class="muted">The display starts each period at these household times. Bedtime stays active until Morning begins. Finished items leave a period after it ends. Unfinished items from earlier in the day stay open.</p><form id="routine-schedule-form" class="settings-form"><label>Morning starts<input name="morningStart" type="time" required></label><label>Afternoon starts<input name="afternoonStart" type="time" required></label><label>Bedtime starts<input name="bedtimeStart" type="time" required></label><button>Save routine times</button></form>';$('.settings-grid').append(panel);form=$('#routine-schedule-form');form.onsubmit=async e=>{e.preventDefault();try{const saved=await api('/api/household/routine-times',{method:'PUT',body:JSON.stringify(formJson(e.target))});Object.assign(me.household,saved);renderTasks();toast('Routine times saved.')}catch(error){toast(error.message)}}}form.elements.morningStart.value=me.household.routineMorningStart||'00:00';form.elements.afternoonStart.value=me.household.routineAfternoonStart||'15:00';form.elements.bedtimeStart.value=me.household.routineBedtimeStart||'19:00'}
function addRoutineSettingsTab(){const tabs=$('#settings-tabs');if(!tabs||$('#settings-tab-routines'))return;const button=document.createElement('button');button.id='settings-tab-routines';button.type='button';button.dataset.settingsTab='routines';button.setAttribute('role','tab');button.setAttribute('aria-controls','settings-panel-routines');button.textContent='Routines';button.onclick=()=>activateSettingsTab('routines');tabs.querySelector('[data-settings-tab="calendars"]').after(button)}
function screenPreview(device){const width=device.screen_width||device.viewport_width,height=device.screen_height||device.viewport_height;if(!width||!height)return '<p class="muted">Open Family Hub on this display to register its resolution.</p>';const ratio=`${width} / ${height}`,seen=device.last_seen_at?new Date(`${device.last_seen_at}Z`).toLocaleString():'Not reported';return `<div class="screen-preview" data-preview-width="${width}" data-preview-height="${height}" style="aspect-ratio:${ratio}"><iframe src="/?preview=1#calendar" title="${escapeAttribute(device.device_name)} calendar preview" tabindex="-1"></iframe></div><dl class="screen-details"><div><dt>Resolution</dt><dd>${width} × ${height}</dd></div><div><dt>Viewport</dt><dd>${device.viewport_width} × ${device.viewport_height}</dd></div><div><dt>Scale</dt><dd>${Number(device.pixel_ratio||1).toFixed(2)}×</dd></div><div><dt>Last seen</dt><dd>${escape(seen)}</dd></div></dl>`}
function sizeScreenPreviews(){for(const preview of $$('.screen-preview')){const width=+preview.dataset.previewWidth,height=+preview.dataset.previewHeight,frame=$('iframe',preview);if(!width||!height||!frame)continue;frame.style.width=`${width}px`;frame.style.height=`${height}px`;frame.style.transform=`scale(${preview.clientWidth/width})`}}
async function setupScreensSettings(){if(me.user?.role!=='adult')return;const grid=$('.settings-grid'),tabs=$('#settings-tabs');if(!grid||!tabs)return;let panel=$('#settings-panel-screens');if(!panel){const button=document.createElement('button');button.id='settings-tab-screens';button.type='button';button.dataset.settingsTab='screens';button.setAttribute('role','tab');button.setAttribute('aria-controls','settings-panel-screens');button.textContent='Screens';button.onclick=()=>{activateSettingsTab('screens');requestAnimationFrame(sizeScreenPreviews)};tabs.querySelector('[data-settings-tab="display"]').after(button);panel=document.createElement('section');panel.id='settings-panel-screens';panel.className='settings-panel screens-panel';panel.dataset.settingsCategory='screens';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','settings-tab-screens');grid.append(panel)}const devices=await api('/api/devices');panel.innerHTML='<h3>Registered screens</h3><p class="muted">Previews use each paired display’s reported resolution.</p><div class="screen-list">'+(devices.length?devices.map(device=>`<article class="screen-card"><h4>${escape(device.device_name)}</h4>${screenPreview(device)}</article>`).join(''):empty('No paired screens yet.'))+'</div>';requestAnimationFrame(sizeScreenPreviews)}
function setupTokenBoardSetting(){if(me.user?.role!=='adult')return;const form=$('#theme-form');if(!form)return;let label=$('#token-board-setting');if(!label){label=document.createElement('label');label.id='token-board-setting';label.className='check-label';label.innerHTML='<input name="tokenBoardEnabled" type="checkbox"> Show token balances on the calendar';form.insertBefore(label,form.querySelector('button'));label.querySelector('input').onchange=async e=>{try{const result=await api('/api/household/token-board',{method:'PUT',body:JSON.stringify({enabled:e.target.checked})});me.household.tokenBoardEnabled=result.tokenBoardEnabled;await renderTokenBoard();toast('Token display saved.')}catch(error){e.target.checked=!e.target.checked;toast(error.message)}}}label.querySelector('input').checked=!!me.household.tokenBoardEnabled}
function setupDisplayTitleSetting(){if(me.user?.role!=='adult')return;let form=$('#display-title-form');if(!form){form=document.createElement('form');form.id='display-title-form';form.className='settings-form display-title-setting adult-only';form.hidden=false;form.innerHTML='<label>Header title<input name="displayTitle" maxlength="60" placeholder="Leave blank to use household name"></label><button>Save title</button>';form.onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/household/display-title',{method:'PUT',body:JSON.stringify({displayTitle:e.target.elements.displayTitle.value})});me.household.displayTitle=result.displayTitle;updateHouseholdTitle();e.target.elements.displayTitle.value=me.household.displayTitle||me.household.name;toast('Header title saved.')}catch(error){toast(error.message)}};$('#identity').after(form)}form.elements.displayTitle.value=me.household.displayTitle||me.household.name}
function setupSettingsTabs(){const grid=$('.settings-grid');if(!grid)return;const categories=[['display','Display','#theme-form,#dim-form,#display-title-form'],['calendars','Calendars','#week-start-form,#calendar-feeds,#calendar-feed-form'],['weather','Weather','#weather-form'],['household','Household','#member-form'],['access','Access','#password-form,#devices,#pair-code,#logout']];const displayTitle=$('#display-title-form'),displayPanel=$('#theme-form')?.closest('.settings-panel');if(displayTitle&&displayPanel&&displayTitle.parentElement!==displayPanel)displayPanel.prepend(displayTitle);const weatherForm=$('#weather-form');if(weatherForm&&!$('#weather-settings-panel')){const source=weatherForm.closest('.settings-panel'),panel=document.createElement('section');panel.id='weather-settings-panel';panel.className='settings-panel';panel.innerHTML='<h3>Weather</h3>';source.after(panel);panel.append(weatherForm)}for(const [id,,selectors]of categories){const panel=$(selectors)?.closest('.settings-panel');if(panel){panel.dataset.settingsCategory=id;panel.id=`settings-panel-${id}`;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',`settings-tab-${id}`)}}for(const panel of $$('.settings-panel',grid))if(!panel.dataset.settingsCategory){panel.dataset.settingsCategory='access';panel.id='settings-panel-access';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','settings-tab-access')}let integrations=$('#settings-panel-integrations');if(!integrations){integrations=document.createElement('section');integrations.id='settings-panel-integrations';integrations.className='settings-panel';integrations.dataset.settingsCategory='integrations';integrations.setAttribute('role','tabpanel');integrations.setAttribute('aria-labelledby','settings-tab-integrations');integrations.innerHTML='<h3>Integrations</h3><p class="muted">Planned connections are shown here before they are available. A connection will have its own enable switch only after its account and sync settings are complete.</p><div class="integration-roadmap"><article><h4>Google and Microsoft calendars</h4><p>Optional account connection for calendar selection and two-way event changes. iCal feeds remain available for read-only calendars.</p><span>Planned</span></article><article><h4>Todoist household tasks</h4><p>Shared project mapping for chores and routines. Start with display and completion sync; keep Family Hub rewards and child views local.</p><span>Planned</span></article><article><h4>AnyList groceries</h4><p>Show a selected household list on the display and mark items complete from the appropriate source.</p><span>Planned</span></article></div>';grid.append(integrations)}let tabs=$('#settings-tabs');if(!tabs){tabs=document.createElement('div');tabs.id='settings-tabs';tabs.className='settings-tabs';tabs.setAttribute('aria-label','Settings sections');tabs.setAttribute('role','tablist');for(const [id,label]of [...categories,['integrations','Integrations']]){const button=document.createElement('button');button.id=`settings-tab-${id}`;button.type='button';button.dataset.settingsTab=id;button.setAttribute('role','tab');button.setAttribute('aria-controls',`settings-panel-${id}`);button.textContent=label;button.onclick=()=>activateSettingsTab(id);tabs.append(button)}tabs.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=$$('[role="tab"]',tabs),current=buttons.indexOf(document.activeElement);if(current<0)return;const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(current+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();activateSettingsTab(buttons[next].dataset.settingsTab)};grid.before(tabs)}activateSettingsTab(grid.dataset.settingsTab||'display')}
function activateSettingsTab(id){const grid=$('.settings-grid');if(!grid)return;grid.dataset.settingsTab=id;$$('[data-settings-tab]').forEach(button=>{const active=button.dataset.settingsTab===id;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1})}
function openView(name){if(name==='plans'||!['calendar','chores','routines','settings','tokens'].includes(name))name='calendar';document.body.dataset.view=name;$$('.view').forEach(v=>v.classList.toggle('mobile-active',v.dataset.view===name));$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));if(name==='settings'){setupDisplayTitleSetting();setupRoutineScheduleSetting();if($('#settings-tabs'))activateSettingsTab($('.settings-grid').dataset.settingsTab||'display');else setupSettingsTabs();addRoutineSettingsTab();setupTokenBoardSetting();setupScreensSettings()}if(name==='tokens')renderTokens();if(dashboard)renderWeather();location.hash=name}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-feed-move]');if(!button)return;const index=feedCatalog.findIndex(feed=>feed.id===+button.dataset.feedMove),swap=index+(button.dataset.direction==='up'?-1:1);if(index<0||swap<0||swap>=feedCatalog.length)return;const ids=feedCatalog.map(feed=>feed.id);[ids[index],ids[swap]]=[ids[swap],ids[index]];try{await api('/api/calendar/feed-order',{method:'PUT',body:JSON.stringify({ids})});await Promise.all([loadSettings(),renderCalendar()])}catch(error){toast(error.message)}});
