function applyDim(){if(!me?.household)return;const theme=['green','slate','blue','warm'].includes(me.household.theme)?me.household.theme:'green',scheduled=!!me.household.dimEnabled&&isDimTime(me.household.dimStart,me.household.dimEnd,new Date(),me.household.timezone||'UTC');if(!scheduled)localStorage.removeItem('family-hub-theme-schedule-override');const override=localStorage.getItem('family-hub-theme-schedule-override'),dark=scheduled&&override?override==='dark':scheduled||localStorage.getItem('family-hub-theme-mode')==='dark';document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.documentElement.classList.toggle('display-dim',dark);document.body.classList.toggle('display-dim',dark);const toggle=$('#theme-toggle');if(toggle){toggle.textContent=dark?'☀':'☾';toggle.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);toggle.setAttribute('aria-pressed',String(dark));toggle.title=scheduled&&override?'Override scheduled dark mode':`Switch to ${dark?'light':'dark'} mode`}}
function isDimTime(start,end,date,timezone){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(start||'')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(end||'')||start===end)return false;const parts=new Intl.DateTimeFormat('en-GB',{timeZone:timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date),hour=parts.find(part=>part.type==='hour').value,now=`${hour==='24'?'00':hour}:${parts.find(part=>part.type==='minute').value}`;return start<end?now>=start&&now<end:now>=start||now<end}
