document.addEventListener('click',async e=>{if(e.target.dataset.move!=='routine'&&e.target.dataset.move!=='chore')return;const list=[...$$(`[data-move="${e.target.dataset.move}"][data-direction="up"]`)].map(button=>+button.dataset.id),index=list.indexOf(+e.target.dataset.id),swap=index+(e.target.dataset.direction==='up'?-1:1);if(swap<0||swap>=list.length)return;const ids=list.slice();[ids[index],ids[swap]]=[ids[swap],ids[index]];try{await api(`/api/${e.target.dataset.move}-order`,{method:'PUT',body:JSON.stringify({ids})});await Promise.all([refresh(),loadSettings()])}catch(error){toast(error.message)}});$('#pair-code').onclick=async()=>{try{$('#pair-output').textContent=(await api('/api/pairing-codes',{method:'POST'})).code}catch(error){toast(error.message)}};$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});await load()};$('#backup-download').onclick=async()=>{try{const response=await fetch('/api/household/backup',{headers:{'X-CSRF-Token':'1'}});if(response.status===401)return showAuth();if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'The backup failed.')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=(response.headers.get('content-disposition')||'').match(/filename="([^"]+)"/)?.[1]||'family-hub-backup.sqlite';link.click();URL.revokeObjectURL(url);toast('Backup downloaded. Keep the file private.')}catch(error){toast(error.message)}};$('#backup-restore').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(!confirm('This replaces the whole household and restarts Family Hub. Continue?'))return;try{const response=await fetch('/api/household/restore',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':'1'},body:file});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Restore failed.');toast('Restore started. Sign in again after Family Hub restarts.')}catch(error){toast(error.message)}};$('#menu-button').onclick=()=>me.user?openView('settings'):showAuth(true);$('#auth-cancel').onclick=()=>load();$('#prev-month').onclick=()=>{pinnedMonth=true;cursor.setMonth(cursor.getMonth()-1);renderCalendar()};$('#next-month').onclick=()=>{pinnedMonth=true;cursor.setMonth(cursor.getMonth()+1);renderCalendar()};$('#today').onclick=()=>{pinnedMonth=false;cursor=new Date();cursor=new Date(cursor.getFullYear(),cursor.getMonth(),1);renderCalendar()};
async function checkDeployment(){try{const response=await fetch('/api/version',{cache:'no-store'});if(!response.ok)return;const {version}=await response.json();if(deploymentVersion&&deploymentVersion!==version){if(window.caches){const keys=await caches.keys();await Promise.all(keys.map(key=>caches.delete(key)))}const next=new URL(location.href);next.searchParams.set('deployed',version);location.replace(next.href);return}deploymentVersion=version}catch{}}
